-- Create evergreen content pages table
CREATE TABLE public.content_pages (
  id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  title TEXT NOT NULL,
  meta_title TEXT,
  meta_description TEXT,
  content TEXT NOT NULL,
  excerpt TEXT,
  featured_image_url TEXT,
  keywords TEXT[],
  is_published BOOLEAN NOT NULL DEFAULT false,
  view_count INTEGER DEFAULT 0,
  created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(),
  updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now()
);

-- Enable RLS
ALTER TABLE public.content_pages ENABLE ROW LEVEL SECURITY;

-- Published pages are publicly readable
CREATE POLICY "Published content pages are publicly readable"
ON public.content_pages
FOR SELECT
USING (is_published = true);

-- Create index for slug lookups
CREATE INDEX idx_content_pages_slug ON public.content_pages(slug);

-- Create index for published pages
CREATE INDEX idx_content_pages_published ON public.content_pages(is_published, created_at DESC);

-- Add trigger for updated_at
CREATE TRIGGER update_content_pages_updated_at
BEFORE UPDATE ON public.content_pages
FOR EACH ROW
EXECUTE FUNCTION public.update_updated_at_column();

-- Insert popular evergreen content pages
INSERT INTO public.content_pages (slug, title, meta_title, meta_description, content, excerpt, keywords, is_published) VALUES
('schengen-visa-guide', 
 'Complete Schengen Visa Guide 2025', 
 'Schengen Visa Requirements & Application Guide 2025',
 'Complete guide to Schengen visa requirements, application process, documents needed, fees, and processing times for all 27 countries.',
 '<h2>What is a Schengen Visa?</h2><p>A Schengen visa allows you to travel freely within 27 European countries for up to 90 days within a 180-day period. This comprehensive guide covers everything you need to know about applying for a Schengen visa.</p><h2>Schengen Countries</h2><p>The Schengen Area includes: Austria, Belgium, Czech Republic, Croatia, Denmark, Estonia, Finland, France, Germany, Greece, Hungary, Iceland, Italy, Latvia, Liechtenstein, Lithuania, Luxembourg, Malta, Netherlands, Norway, Poland, Portugal, Slovakia, Slovenia, Spain, Sweden, and Switzerland.</p><h2>Types of Schengen Visas</h2><ul><li><strong>Short-stay visa (Type C):</strong> For tourism, business, or family visits up to 90 days</li><li><strong>Airport transit visa (Type A):</strong> For transiting through Schengen airports</li><li><strong>Long-stay visa (Type D):</strong> For stays longer than 90 days</li></ul><h2>Required Documents</h2><ul><li>Valid passport (valid for at least 3 months beyond intended stay)</li><li>Completed Schengen visa application form</li><li>Two recent passport-sized photos</li><li>Travel insurance (minimum coverage €30,000)</li><li>Proof of accommodation</li><li>Flight itinerary</li><li>Proof of financial means</li><li>Cover letter explaining purpose of visit</li><li>Employment letter or business registration</li></ul><h2>Application Process</h2><ol><li>Determine which Schengen country to apply to (main destination or first entry point)</li><li>Book an appointment at the embassy/consulate or visa application center</li><li>Prepare all required documents</li><li>Attend your appointment and submit documents</li><li>Pay the visa fee (€80 for adults, €40 for children 6-12)</li><li>Wait for processing (typically 15 working days)</li></ol><h2>Processing Time & Fees</h2><p>Standard processing time is 15 calendar days but can take up to 30-60 days in exceptional cases. The fee is €80 for adults and €40 for children aged 6-12 years. Children under 6 are exempt from fees.</p><h2>Tips for Success</h2><ul><li>Apply at least 3-4 weeks before your planned travel</li><li>Ensure all documents are complete and accurate</li><li>Show strong ties to your home country</li><li>Provide genuine travel plans with realistic itinerary</li><li>Have sufficient funds for your stay</li></ul>',
 'Complete guide to Schengen visa requirements, application process, documents, fees and processing times for traveling to 27 European countries.',
 ARRAY['schengen visa', 'europe visa', 'schengen countries', 'schengen visa requirements', 'europe travel'],
 true),

('us-visit-visa-guide',
 'US Tourist Visa (B1/B2) Complete Guide 2025',
 'US Tourist Visa B2 Application Guide & Requirements 2025',
 'Complete guide to US tourist visa (B-2) application process, requirements, interview tips, processing times and fees.',
 '<h2>US Tourist Visa Overview</h2><p>The B-2 visa is for tourism, vacation, medical treatment, or visiting friends and family in the United States. This guide provides comprehensive information on how to apply successfully.</p><h2>B1/B2 Visa Types</h2><ul><li><strong>B-1 Visa:</strong> For business purposes, attending conferences, negotiating contracts</li><li><strong>B-2 Visa:</strong> For tourism, vacation, medical treatment, visiting friends/family</li><li><strong>B-1/B-2 Combined:</strong> For both business and tourism purposes</li></ul><h2>Eligibility Requirements</h2><ul><li>Valid passport (valid for at least 6 months beyond intended stay)</li><li>Completed DS-160 form</li><li>Visa application fee payment receipt</li><li>Proof of strong ties to home country</li><li>Proof of financial ability to cover expenses</li><li>Intent to return to home country</li></ul><h2>Required Documents</h2><ul><li>Valid passport</li><li>DS-160 confirmation page</li><li>Visa fee payment receipt</li><li>Photo as per US visa specifications</li><li>Previous US visas (if any)</li><li>Employment letter or business documents</li><li>Bank statements (last 6 months)</li><li>Property documents</li><li>Family ties documents</li><li>Travel itinerary and hotel bookings</li><li>Invitation letter (if visiting someone)</li></ul><h2>Application Process</h2><ol><li>Complete the DS-160 form online</li><li>Pay the visa application fee ($185)</li><li>Schedule visa interview appointment</li><li>Gather required documents</li><li>Attend visa interview at US Embassy/Consulate</li><li>Submit biometrics (fingerprints)</li><li>Wait for visa processing</li></ol><h2>Visa Interview Tips</h2><ul><li>Be honest and confident in your answers</li><li>Dress professionally</li><li>Bring all required documents organized</li><li>Clearly explain purpose of visit</li><li>Demonstrate strong ties to home country</li><li>Show sufficient financial resources</li><li>Keep answers brief and to the point</li></ul><h2>Processing Time & Fees</h2><p>The visa application fee is $185. Processing time varies by location but typically takes 3-5 business days after the interview. In some cases, administrative processing may take several weeks.</p><h2>Common Rejection Reasons</h2><ul><li>Insufficient ties to home country</li><li>Lack of financial resources</li><li>Immigration intent suspected</li><li>Incomplete or false information</li><li>Previous immigration violations</li></ul>',
 'Learn how to apply for US tourist visa (B-2), required documents, interview process, fees, and tips for successful application.',
 ARRAY['us tourist visa', 'b2 visa', 'usa visit visa', 'us visa application', 'american visa'],
 true),

('dubai-visit-visa-guide',
 'Dubai Visit Visa Guide 2025 - UAE Tourist Visa',
 'Dubai Visit Visa Requirements & Application 2025',
 'Complete guide to Dubai visit visa, UAE tourist visa requirements, online application process, fees, and documents needed.',
 '<h2>Dubai Visit Visa Overview</h2><p>Dubai (UAE) offers various types of visit visas for tourists, business visitors, and family visits. This guide covers everything you need to know about obtaining a Dubai visit visa.</p><h2>Types of UAE Visit Visas</h2><ul><li><strong>14-day visa:</strong> Short visit for tourism or business</li><li><strong>30-day visa:</strong> Standard tourist visa (single or multiple entry)</li><li><strong>60-day visa:</strong> Extended tourist visa</li><li><strong>90-day visa:</strong> Long-term tourist visa (single or multiple entry)</li></ul><h2>Who Needs a Visa?</h2><p>Citizens from over 50 countries get visa on arrival or are visa-exempt. Citizens from other countries need to apply for a visa in advance. GCC residents can obtain visa on arrival.</p><h2>Visa Exemption Countries</h2><p>Citizens from USA, UK, EU countries, Australia, Canada, and many others can enter UAE without a visa for varying periods (14-90 days depending on nationality).</p><h2>Required Documents</h2><ul><li>Valid passport (minimum 6 months validity)</li><li>Passport copy and photo page</li><li>Recent passport-sized photograph</li><li>Completed visa application form</li><li>Confirmed flight tickets</li><li>Hotel booking confirmation</li><li>Travel insurance</li><li>Bank statements (for certain nationalities)</li></ul><h2>Application Process</h2><ol><li>Choose visa type and duration</li><li>Apply through airline, hotel, travel agency, or online</li><li>Submit required documents</li><li>Pay visa fees</li><li>Receive visa via email (e-visa)</li><li>Print visa and carry with passport</li></ol><h2>Visa Fees</h2><ul><li>14-day visa: AED 100-250</li><li>30-day single entry: AED 350-450</li><li>30-day multiple entry: AED 650-750</li><li>60-day single/multiple entry: AED 1,000-1,200</li><li>90-day single entry: AED 1,000-1,200</li><li>90-day multiple entry: AED 2,000-2,500</li></ul><p>Fees vary depending on application channel and may include service charges.</p><h2>Processing Time</h2><p>Standard processing takes 3-5 working days. Express services available for faster processing (24-48 hours) at additional cost.</p><h2>Visa Extension</h2><p>Tourist visas can be extended once for 30 days. Application must be made before current visa expires. Extension fee is approximately AED 600-750.</p><h2>Important Tips</h2><ul><li>Apply at least 1 week before travel</li><li>Ensure passport has at least 6 months validity</li><li>Print visa and carry with passport</li><li>Keep hotel bookings and return tickets ready at immigration</li><li>Dubai does not stamp visit visas in passport - it''s all electronic</li></ul>',
 'Complete guide to Dubai visit visa application, requirements, types, fees, processing time, and how to apply for UAE tourist visa.',
 ARRAY['dubai visa', 'uae visit visa', 'dubai tourist visa', 'emirates visa', 'dubai travel'],
 true),

('uk-visit-visa-guide',
 'UK Visit Visa Guide 2025 - Standard Visitor Visa',
 'UK Standard Visitor Visa Requirements & Application 2025',
 'Complete guide to UK visit visa application process, requirements, documents, fees, processing times and interview tips.',
 '<h2>UK Standard Visitor Visa Overview</h2><p>The UK Standard Visitor visa allows you to visit the UK for tourism, business, medical treatment, or to see family and friends for up to 6 months. This guide covers the complete application process.</p><h2>What You Can Do</h2><ul><li>Tourism and leisure activities</li><li>Visit family and friends</li><li>Business meetings and conferences</li><li>Short-term study (up to 6 months)</li><li>Medical treatment</li><li>Transit through UK</li></ul><h2>Eligibility Requirements</h2><ul><li>Genuine intention to visit temporarily</li><li>Sufficient funds to support yourself</li><li>Ability to pay for return journey</li><li>Intent to leave UK at end of visit</li><li>Not intending to work or settle</li></ul><h2>Required Documents</h2><ul><li>Valid passport or travel document</li><li>Previous passports</li><li>Bank statements (last 6 months)</li><li>Payslips or employment letter</li><li>Property documents</li><li>Travel itinerary and accommodation details</li><li>Invitation letter (if visiting someone)</li><li>Sponsor documents (if applicable)</li><li>Business documents (for business visits)</li><li>Marriage certificate and family documents</li></ul><h2>Application Process</h2><ol><li>Complete online application form</li><li>Pay visa fee online</li><li>Book biometric appointment</li><li>Attend appointment at visa application center</li><li>Submit documents and biometrics</li><li>Wait for decision</li><li>Collect passport with visa</li></ol><h2>Visa Fees</h2><ul><li>6-month standard visitor visa: £115</li><li>2-year multiple entry: £433</li><li>5-year multiple entry: £788</li><li>10-year multiple entry: £988</li></ul><p>Priority and super priority services available at additional cost.</p><h2>Processing Time</h2><p>Standard processing: 3 weeks<br>Priority service: 5 working days (additional £250)<br>Super priority: 24 hours (additional £1,000)</p><h2>Financial Requirements</h2><p>You must show you can support yourself during your visit. Required amount varies but generally:</p><ul><li>£95-£100 per day for your stay</li><li>Consistent banking history</li><li>Regular income or savings</li><li>Travel costs covered</li></ul><h2>Common Refusal Reasons</h2><ul><li>Insufficient funds or unclear source of income</li><li>Weak ties to home country</li><li>Immigration history issues</li><li>Unclear purpose of visit</li><li>Incomplete or false documents</li><li>Previous visa violations</li></ul><h2>Tips for Success</h2><ul><li>Be honest in application</li><li>Provide complete documentation</li><li>Show strong ties to home country</li><li>Demonstrate sufficient funds</li><li>Clear travel plans and itinerary</li><li>Apply well in advance of travel</li></ul>',
 'Learn how to apply for UK standard visitor visa, requirements, documents needed, fees, processing times and tips for approval.',
 ARRAY['uk visit visa', 'uk tourist visa', 'uk standard visitor visa', 'britain visa', 'england visa'],
 true),

('canada-visit-visa-guide',
 'Canada Visitor Visa Guide 2025 - TRV Application',
 'Canada Visitor Visa (TRV) Requirements & Application 2025',
 'Complete guide to Canada visitor visa application, requirements, documents, fees, processing times, and biometrics.',
 '<h2>Canada Visitor Visa (TRV) Overview</h2><p>A Canada Visitor Visa, officially called a Temporary Resident Visa (TRV), allows you to visit Canada for tourism, family visits, or business for up to 6 months. This guide provides everything you need to apply successfully.</p><h2>Who Needs a Visa?</h2><p>Citizens from visa-required countries need a TRV to visit Canada. Citizens from visa-exempt countries may need an Electronic Travel Authorization (eTA) instead. US citizens need neither.</p><h2>Types of Visitor Visas</h2><ul><li><strong>Single Entry:</strong> Valid for one entry into Canada</li><li><strong>Multiple Entry:</strong> Allows multiple entries during validity period (up to 10 years)</li></ul><h2>Eligibility Requirements</h2><ul><li>Valid travel document (passport)</li><li>Good health</li><li>No criminal or immigration-related convictions</li><li>Ties to home country</li><li>Sufficient funds for stay and return</li><li>Intent to leave Canada at end of visit</li></ul><h2>Required Documents</h2><ul><li>Valid passport (for duration of stay)</li><li>Completed application form (IMM 5257)</li><li>Family information form (IMM 5645)</li><li>Two recent passport photos</li><li>Proof of financial support (bank statements, 6 months)</li><li>Purpose of visit letter</li><li>Travel itinerary</li><li>Employment letter or proof of enrollment</li><li>Property documents or lease agreement</li><li>Marriage certificate and family documents</li><li>Invitation letter (if visiting family/friends)</li><li>Previous travel history</li></ul><h2>Application Process</h2><ol><li>Determine if you need a visa or eTA</li><li>Create online account on IRCC website</li><li>Complete application form online</li><li>Upload required documents</li><li>Pay application fee</li><li>Submit application</li><li>Provide biometrics at VAC (if required)</li><li>Wait for processing</li><li>Submit passport if approved</li></ol><h2>Biometrics Requirement</h2><p>Most applicants aged 14-79 must provide biometrics (fingerprints and photo) at a Visa Application Center (VAC). Fee is CAD 85 per person or CAD 170 for families.</p><h2>Visa Fees</h2><ul><li>Visitor visa (single/multiple entry): CAD 100</li><li>Biometrics: CAD 85 per person, CAD 170 per family</li><li>Family rate (5+ people): CAD 500 maximum</li></ul><h2>Processing Time</h2><p>Processing times vary by country of application. Generally:</p><ul><li>Online applications: 2-8 weeks</li><li>Paper applications: Longer processing times</li><li>Check current times on IRCC website for your country</li></ul><h2>Super Visa for Parents/Grandparents</h2><p>Super Visa allows parents and grandparents of Canadian citizens/PRs to stay for up to 5 years per visit. Requirements include:</p><ul><li>Medical insurance (minimum CAD 100,000 coverage)</li><li>Letter of invitation from child/grandchild</li><li>Child''s proof of income (meeting LICO requirements)</li><li>Medical examination</li></ul><h2>Common Refusal Reasons</h2><ul><li>Insufficient ties to home country</li><li>Weak financial situation</li><li>Unclear purpose of visit</li><li>Travel history concerns</li><li>Previous immigration violations</li><li>Incomplete application</li></ul><h2>Tips for Approval</h2><ul><li>Apply online for faster processing</li><li>Provide complete documentation</li><li>Show strong ties to home country</li><li>Demonstrate sufficient funds</li><li>Write clear purpose of visit letter</li><li>Include previous travel history</li><li>Explain any gaps in employment</li><li>Be truthful in application</li></ul>',
 'Complete guide to Canada visitor visa (TRV) application process, requirements, documents needed, fees, biometrics, and processing times.',
 ARRAY['canada visitor visa', 'canada trv', 'canada tourist visa', 'canada visit', 'canadian visa'],
 true);